-- RiskWeave database schema through migration 0010, for pasting into a SQL console
-- (e.g. the Supabase SQL editor) instead of running `ringsentinel-migrate`.
-- Generated by: uv run --locked ringsentinel-migrate --sql
-- Run once on an empty database, then run riskweave_lockdown.sql.

BEGIN;

CREATE TABLE alembic_version (
    version_num VARCHAR(32) NOT NULL, 
    CONSTRAINT alembic_version_pkc PRIMARY KEY (version_num)
);

-- Running upgrade  -> 0001

CREATE TABLE users (
    id VARCHAR(80) NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    PRIMARY KEY (id)
);

CREATE TABLE investigations (
    id VARCHAR(80) NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    owner_id VARCHAR(80) NOT NULL, 
    name VARCHAR(120) NOT NULL, 
    status VARCHAR(9) NOT NULL, 
    source_metadata JSON NOT NULL, 
    analysis_metadata JSON NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(owner_id) REFERENCES users (id), 
    CONSTRAINT status CHECK (status IN ('created', 'uploading', 'queued', 'running', 'completed', 'failed'))
);

CREATE INDEX ix_investigations_owner_id ON investigations (owner_id);

CREATE TABLE artifacts (
    id VARCHAR(80) NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    investigation_id VARCHAR(80) NOT NULL, 
    original_name VARCHAR(200) NOT NULL, 
    storage_key VARCHAR(100) NOT NULL, 
    content_type VARCHAR(100) NOT NULL, 
    size_bytes INTEGER NOT NULL, 
    checksum VARCHAR(64) NOT NULL, 
    PRIMARY KEY (id), 
    UNIQUE (investigation_id, checksum), 
    FOREIGN KEY(investigation_id) REFERENCES investigations (id), 
    UNIQUE (storage_key)
);

CREATE INDEX ix_artifacts_investigation_id ON artifacts (investigation_id);

CREATE TABLE analysis_runs (
    id VARCHAR(80) NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    investigation_id VARCHAR(80) NOT NULL, 
    artifact_id VARCHAR(80) NOT NULL, 
    status VARCHAR(9) NOT NULL, 
    active_slot VARCHAR(80), 
    idempotency_key VARCHAR(80) NOT NULL, 
    started_at TIMESTAMP WITH TIME ZONE, 
    completed_at TIMESTAMP WITH TIME ZONE, 
    error_code VARCHAR(80), 
    error_message_safe VARCHAR(200), 
    version_metadata JSON NOT NULL, 
    configuration_snapshot JSON NOT NULL, 
    result_reference VARCHAR(100), 
    result_checksum VARCHAR(64), 
    PRIMARY KEY (id), 
    UNIQUE (investigation_id, idempotency_key), 
    FOREIGN KEY(investigation_id) REFERENCES investigations (id), 
    FOREIGN KEY(artifact_id) REFERENCES artifacts (id), 
    CONSTRAINT status CHECK (status IN ('created', 'uploading', 'queued', 'running', 'completed', 'failed')), 
    UNIQUE (active_slot)
);

CREATE INDEX ix_analysis_runs_investigation_id ON analysis_runs (investigation_id);

CREATE INDEX ix_analysis_runs_artifact_id ON analysis_runs (artifact_id);

CREATE INDEX ix_analysis_runs_status ON analysis_runs (status);

INSERT INTO alembic_version (version_num) VALUES ('0001') RETURNING alembic_version.version_num;

-- Running upgrade 0001 -> 0002

CREATE TABLE candidate_reviews (
    run_id VARCHAR(80) NOT NULL, 
    candidate_id VARCHAR(100) NOT NULL, 
    disposition VARCHAR(30) NOT NULL, 
    version INTEGER NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    PRIMARY KEY (run_id, candidate_id), 
    CONSTRAINT review_positive_version CHECK (version > 0), 
    CONSTRAINT review_disposition CHECK (disposition IN ('unreviewed', 'investigating', 'escalated', 'dismissed')), 
    FOREIGN KEY(run_id) REFERENCES analysis_runs (id)
);

CREATE TABLE review_audit (
    id VARCHAR(80) NOT NULL, 
    run_id VARCHAR(80) NOT NULL, 
    candidate_id VARCHAR(100) NOT NULL, 
    actor_id VARCHAR(80) NOT NULL, 
    previous_disposition VARCHAR(30) NOT NULL, 
    disposition VARCHAR(30) NOT NULL, 
    version INTEGER NOT NULL, 
    note VARCHAR(2000) NOT NULL, 
    idempotency_key VARCHAR(80) NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    PRIMARY KEY (id), 
    FOREIGN KEY(run_id, candidate_id) REFERENCES candidate_reviews (run_id, candidate_id), 
    UNIQUE (run_id, candidate_id, version), 
    UNIQUE (run_id, candidate_id, idempotency_key), 
    FOREIGN KEY(actor_id) REFERENCES users (id)
);

UPDATE alembic_version SET version_num='0002' WHERE alembic_version.version_num = '0001';

-- Running upgrade 0002 -> 0003

CREATE TABLE storage_deletions (
    key VARCHAR(100) NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    attempts INTEGER NOT NULL, 
    last_attempt_at TIMESTAMP WITH TIME ZONE, 
    last_error_code VARCHAR(40), 
    PRIMARY KEY (key)
);

UPDATE alembic_version SET version_num='0003' WHERE alembic_version.version_num = '0002';

-- Running upgrade 0003 -> 0004

CREATE TABLE stored_objects (
    key VARCHAR(100) NOT NULL, 
    content BYTEA NOT NULL, 
    size_bytes BIGINT NOT NULL, 
    checksum VARCHAR(64) NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    PRIMARY KEY (key), 
    CONSTRAINT stored_object_size CHECK (size_bytes >= 0)
);

ALTER TABLE analysis_runs ADD COLUMN execution_deadline TIMESTAMP WITH TIME ZONE;

ALTER TABLE analysis_runs ADD COLUMN executor_slot VARCHAR(80);

CREATE UNIQUE INDEX uq_analysis_runs_executor_slot ON analysis_runs (executor_slot);

CREATE INDEX ix_analysis_runs_execution_deadline ON analysis_runs (execution_deadline);

UPDATE alembic_version SET version_num='0004' WHERE alembic_version.version_num = '0003';

-- Running upgrade 0004 -> 0005

CREATE TABLE upload_sessions (
    id VARCHAR(80) NOT NULL, 
    created_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    updated_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    investigation_id VARCHAR(80) NOT NULL, 
    idempotency_key VARCHAR(80) NOT NULL, 
    name VARCHAR(200) NOT NULL, 
    size_bytes BIGINT NOT NULL, 
    checksum VARCHAR(64) NOT NULL, 
    chunk_count INTEGER NOT NULL, 
    status VARCHAR(16) NOT NULL, 
    active_slot VARCHAR(80), 
    previous_status VARCHAR(16) NOT NULL, 
    artifact_id VARCHAR(80), 
    expires_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    PRIMARY KEY (id), 
    UNIQUE (investigation_id, idempotency_key), 
    UNIQUE (active_slot), 
    FOREIGN KEY(investigation_id) REFERENCES investigations (id), 
    FOREIGN KEY(artifact_id) REFERENCES artifacts (id)
);

CREATE INDEX ix_upload_sessions_investigation_id ON upload_sessions (investigation_id);

CREATE INDEX ix_upload_sessions_expires_at ON upload_sessions (expires_at);

CREATE TABLE upload_parts (
    upload_id VARCHAR(80) NOT NULL, 
    part_index INTEGER NOT NULL, 
    content BYTEA NOT NULL, 
    size_bytes BIGINT NOT NULL, 
    checksum VARCHAR(64) NOT NULL, 
    PRIMARY KEY (upload_id, part_index), 
    CONSTRAINT upload_part_size CHECK (size_bytes > 0), 
    FOREIGN KEY(upload_id) REFERENCES upload_sessions (id)
);

UPDATE alembic_version SET version_num='0005' WHERE alembic_version.version_num = '0004';

-- Running upgrade 0005 -> 0006

ALTER TABLE analysis_runs ADD COLUMN dispatch_state VARCHAR(16);

CREATE TABLE analysis_dispatches (
    run_id VARCHAR(80) NOT NULL, 
    ticket VARCHAR(36) NOT NULL, 
    budget_month VARCHAR(7) NOT NULL, 
    attempts INTEGER NOT NULL, 
    workflow_id VARCHAR(80), 
    lease_token VARCHAR(36), 
    lease_until TIMESTAMP WITH TIME ZONE, 
    next_attempt_at TIMESTAMP WITH TIME ZONE NOT NULL, 
    last_error_code VARCHAR(40), 
    PRIMARY KEY (run_id), 
    FOREIGN KEY(run_id) REFERENCES analysis_runs (id)
);

CREATE INDEX ix_analysis_dispatches_next_attempt_at ON analysis_dispatches (next_attempt_at);

CREATE TABLE dispatch_budgets (
    month VARCHAR(7) NOT NULL, 
    starts INTEGER NOT NULL, 
    PRIMARY KEY (month)
);

CREATE TABLE dispatch_schedules (
    day VARCHAR(10) NOT NULL, 
    attempts INTEGER NOT NULL, 
    workflow_id VARCHAR(80), 
    lease_token VARCHAR(36), 
    lease_until TIMESTAMP WITH TIME ZONE, 
    PRIMARY KEY (day)
);

UPDATE alembic_version SET version_num='0006' WHERE alembic_version.version_num = '0005';

-- Running upgrade 0006 -> 0007

ALTER TABLE analysis_runs ADD COLUMN result_size_bytes BIGINT;

CREATE TABLE result_fragments (
    run_id VARCHAR(80) NOT NULL, 
    part_index INTEGER NOT NULL, 
    size_bytes INTEGER NOT NULL, 
    checksum VARCHAR(64) NOT NULL, 
    PRIMARY KEY (run_id, part_index), 
    CONSTRAINT result_fragment_index CHECK (part_index >= 0 AND part_index < 250), 
    CONSTRAINT result_fragment_size CHECK (size_bytes > 0 AND size_bytes <= 2000000), 
    FOREIGN KEY(run_id) REFERENCES analysis_runs (id) ON DELETE CASCADE
);

UPDATE alembic_version SET version_num='0007' WHERE alembic_version.version_num = '0006';

-- Running upgrade 0007 -> 0008

ALTER TABLE analysis_runs ADD COLUMN candidate_count INTEGER;

UPDATE alembic_version SET version_num='0008' WHERE alembic_version.version_num = '0007';

-- Running upgrade 0008 -> 0009

ALTER TABLE analysis_runs ADD COLUMN candidate_index JSON;

CREATE TABLE result_sections (
    run_id VARCHAR(80) NOT NULL, 
    kind VARCHAR(16) NOT NULL, 
    candidate_id VARCHAR(100) NOT NULL, 
    ordinal INTEGER NOT NULL, 
    byte_offset BIGINT NOT NULL, 
    size_bytes BIGINT NOT NULL, 
    checksum VARCHAR(64) NOT NULL, 
    PRIMARY KEY (run_id, kind, candidate_id), 
    CONSTRAINT result_section_range CHECK (byte_offset >= 0 AND size_bytes > 0), 
    FOREIGN KEY(run_id) REFERENCES analysis_runs (id) ON DELETE CASCADE
);

UPDATE alembic_version SET version_num='0009' WHERE alembic_version.version_num = '0008';

-- Running upgrade 0009 -> 0010

CREATE INDEX ix_result_sections_page ON result_sections (run_id, kind, ordinal);

UPDATE alembic_version SET version_num='0010' WHERE alembic_version.version_num = '0009';

COMMIT;

